"""Conductivity requirement curve on frozen exact-family temperature histories.
Cross-plane active-layer k and in-plane cap k are independent scenario inputs.
"""
from pathlib import Path
import json,csv,math,hashlib
P=Path(__file__).resolve().parent
read=lambda p:json.loads(Path(p).read_text());sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
h=read(P/'temperature-histories.json');g=read(P/'results.json');geom=g['geometry'];depth=geom['active_depth_m'];rpost=geom['plenum_height_m']/(geom['post_conductivity_W_m_K']*geom['thermal_post_area_fraction']);ks=[.2,.5,1.,2.,4.,10.];threshold=1700.;rows=[];profiles=[];screen=[]
for p in h['profiles']:
 f=Path(p['csv']);assert sha(f)==p['sha256'];data=list(csv.DictReader(f.open()));t=[float(x['relative_to_prompt_arrival_s']) for x in data];base=[float(x['front_bulk_k50_K']) for x in data];q=[float(x['material_W_m2'])+float(x['delayed_decay_W_m2']) for x in data];profiles.append((p,t,base,q))
 # Algebraic conductivity required at every saved time. Chosen temperature
 # screen is not a material allowable or a proposed operating limit.
 denom=[threshold-b-f*rpost for b,f in zip(base,q)]
 if min(denom)<=0:required=None;ix=denom.index(min(denom))
 else:
  req=[f*depth/d for f,d in zip(q,denom)];required=max(req);ix=req.index(required)
 screen.append({'stage':p['stage'],'selection':p['selection'],'minimum_layer_k_W_m_K_for_chosen_screen':required,'controlling_relative_time_s':t[ix],'base_front_K':base[ix],'q_material_plus_decay_W_m2':q[ix],'postgap_rise_K':q[ix]*rpost})
for k in ks:
 out=[];res=depth/k+rpost
 for p,t,base,q in profiles:
  T=[b+f*res for b,f in zip(base,q)];i=max(range(len(T)),key=T.__getitem__);out.append({'stage':p['stage'],'selection':p['selection'],'maximum_front_K':T[i],'relative_time_at_peak_s':t[i],'base_front_K_at_peak':base[i],'layer_rise_K_at_peak':q[i]*depth/k,'postgap_rise_K_at_peak':q[i]*rpost,'peak_flux_resistance_rise_K':max(q)*res})
 winner=max(out,key=lambda x:x['maximum_front_K']);rows.append({'layer_k_W_m_K':k,'layer_resistance_m2_K_W':depth/k,'postgap_resistance_m2_K_W':rpost,'total_added_resistance_m2_K_W':res,'through_layer_diffusion_timescale_s':2000*1800*depth**2/k,'maximum_front_K_over_profiles':winner['maximum_front_K'],'controlling_profile':winner['stage']+'/'+winner['selection'],'per_profile':out})
cap=[]
for k in [.2,.5,1.,2.,4.,10.,50.,100.]:
 rc=geom['slot_full_width_m']**2/(8*k*geom['cap_thickness_m']);cap.append({'cap_inplane_k_W_m_K':k,'supported_span_peak_rise_per_absorbed_flux_m2_K_W':rc,'span_diffusion_timescale_s':geom['slot_full_width_m']**2*2000*1800/k,'per_stage_full_incident_prompt_absorption_rise_K_upper':{s['stage']:s['prompt_radial_peak_W_m2']*rc for s in g['stages']},'peak_material_cap_span_rise_K_upper':max(max(x[3]) for x in profiles)*rc})
# Capture an explicit gas design case; all numbers are a linked conditional
# interface. No new pump/cold-panel performance is inferred here.
gp=P.parent/'gas/joint-ports.json';gas=read(gp);selected=next(s for s in gas['scenarios'] if math.isclose(s['downstream_speed_target_m3_s_per_wall_m2_each_species'],.001) and math.isclose(s['shared_mouth_area_fraction'],1e-4) and math.isclose(s['net_molecular_transmission'],.1));leak=next(s for s in selected['hot_photon_leakage_into5K_sensitivity'] if s['fraction_of_admitted1000K_aperture_energy_reaching5K']==1e-4)
summary={'downstream_speed_target_m3_s_per_wall_m2_each_species':.001,'shared_mouth_area_fraction':1e-4,'net_molecular_transmission':.1,'hot_heat_bypass_W_m2_upper':selected['hot_to_cold_bypass_upper_W_m2'],'Hgetter_Hecryo_active_area_fractions':selected['required_active_panel_area_fraction_Hgetter_Hecryo'],'He_200K_to5K_radiation_W_m2':selected['He_200K_to5K_radiation_W_m2_if_full_200K_view'],'refrigeration_W_m2_before_hot_photon_tail':selected['He_refrigeration_W_m2_etaCarnot0p5_at200K_sink'],'extra_refrigeration_W_m2_hot_transmission1e4':leak['additional_refrigeration_W_m2_etaCarnot0p5'],'active_hardware_mass_sensitivity':selected['active_hardware_mass_sensitivity_kg_per_wall_m2'],'energy_boundary':'Hot bypass removes engine-eligible heat once. Internal200K→5K transfer is not a second energy source. Refrigeration electricity is a separate debit. Existing bypass/service allocations must be matched before addition.'}
assert all(rows[i]['maximum_front_K_over_profiles']>rows[i+1]['maximum_front_K_over_profiles'] for i in range(len(rows)-1))
required=max(x['minimum_layer_k_W_m_K_for_chosen_screen'] for x in screen);targetrow=max(screen,key=lambda x:x['minimum_layer_k_W_m_K_for_chosen_screen']);checks=[]
for p,t,base,q in profiles:
 assert max(b+f*(depth/required+rpost) for b,f in zip(base,q))<=threshold+1e-10;checks.append('chosen_screen:'+p['stage']+'/'+p['selection'])
assert abs(max(b+f*(depth/required+rpost) for _,_,base,q in profiles for b,f in zip(base,q))-threshold)<1e-9;checks.append('chosen_screen_active')
assert math.isclose(next(x for x in rows if x['layer_k_W_m_K']==4)['maximum_front_K_over_profiles'],max(x['maximum_K_with150um_k4_and_postgap'] for x in g['thermal_profiles']),abs_tol=1e-10);checks.append('k4_previous_geometry_replay')
out={'scope':__doc__,'code_sha256':sha(__file__),'inputs_sha256':{str(p):sha(p) for p in [P/'temperature-histories.json',P/'results.json',gp]},'layer_rows':rows,'chosen_temperature_screen':{'temperature_K':threshold,'status':'Illustrative chosen material-arrival screen; not a measured allowable, universal operating limit or full prompt-temperature condition.','minimum_layer_k_W_m_K':required,'controlling_profile':targetrow,'per_profile':screen},'cap_rows':cap,'geometry_interpretation':{'postgap_resistance_m2_K_W':rpost,'layer_resistance_k4_m2_K_W':depth/4,'post_fraction_sensitivity_at_kpost50':{str(f):geom['plenum_height_m']/(50*f) for f in [.1,.25,.5,1.]},'through_continuous_cap_vertical_resistance_at_knormal4_m2_K_W':geom['cap_thickness_m']/4,'vertical_cap_scope':'Already part of the150um active-layer series resistance. Do not add it again. The local unsupported-span rise is a separate in-plane path affecting0.5% of projected area.','thermal_scope':'Saved material/decay time profiles use a fixed mean pickup and conserved full-source heat. Additive skin resistance is quasi-steady on the material pulse and conservative because the prior intact layer resistance is not subtracted. Prompt spectral-depth dynamics, temperature-dependent properties, contacts and constitutive damage remain separate.'},'gas_linked_case':summary,'checks_passed':len(checks),'checks':checks,'limits':['Temperatures are maxima over the seven frozen detailed profiles including allthreeC13 events, not an exhaustive new fine-time simulation of every dispatch event.','The lowk skin diffusion timescale stays below0.405s; rapid prompt heating must use its separate finite-depth transient and cap lateral response.','No material failure temperature or conductivity credible interval is inferred. k values are requirements/sensitivities.','Layer normal conductivity and cap in-plane conductivity are independent tensor properties.','Gas mouth, baffle transmission, loaded capture and cryostat view factor are joint apparatus qualifications; panel-only mass does not include manifolds, shields, compressors or regeneration hardware.']}
(P/'conductivity.json').write_text(json.dumps(out,indent=2,allow_nan=False)+'\n');print(json.dumps({'curve':[{'k':r['layer_k_W_m_K'],'R':r['total_added_resistance_m2_K_W'],'T':r['maximum_front_K_over_profiles']} for r in rows],'screen':required,'gas':summary,'checks_passed':len(checks)},indent=2))
